package vn.gasstation.integration.seenpro.mapper;
import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;import org.springframework.stereotype.Component;import vn.gasstation.integration.seenpro.model.SeenProRevenueReport;import vn.gasstation.report.domain.*;
@Component public class SeenProRevenueReportMapper {public RevenueReport map(SeenProRevenueReport source,LocalDate from,LocalDate to){var v=source.todayValues();return new RevenueReport(from,to,decimal(v.get(0),true),decimal(v.get(1),false),integer(v.get(2)),decimal(v.get(3),true),decimal(v.get(4),false),integer(v.get(5)),map(source.fuels()),map(source.pumps()),map(source.invoices()));}private List<RevenueBreakdown> map(List<SeenProRevenueReport.SeenProRevenueRow> rows){return rows.stream().map(r->new RevenueBreakdown(r.name(),decimal(r.liters(),false),decimal(r.revenue(),true),integer(r.count()))).toList();}private long integer(String value){try{return Long.parseLong(clean(value).replaceAll("[^0-9-]",""));}catch(Exception ignored){return 0;}}private BigDecimal decimal(String value,boolean wholeCurrency){String clean=clean(value).replaceAll("[^0-9,.-]","");if(clean.isBlank())return BigDecimal.ZERO;if(wholeCurrency)return new BigDecimal(clean.replace(".","").replace(",",""));int comma=clean.lastIndexOf(','),dot=clean.lastIndexOf('.');if(comma>dot)clean=clean.replace(".","").replace(',','.');else clean=clean.replace(",","");return new BigDecimal(clean);}private String clean(String value){return value==null?"":value.trim();}}
